+  const isRecord = (value) => typeof value === "object" && value !== null && !Array.isArray(value);
+  const isListOfRecords = (value) => Array.isArray(value) && value.every(isRecord);
+
+  /** テストを、確かめているものとして数えるか。未実装(提案)と、このブランチで消したものは数えない。 */
+  const isVerifying = (test) => test.status !== "todo" && test.status !== "removed";
+
+  /**
+   * やりとりの両端が図の箱か。構造マップで選べるのは、両端が箱のやりとりだけ。
+   * @param entryAt パスから木の項目を引く表
+   */
+  const isDrawnMessage = (message, entryAt) => [message.from, message.to].every((path) => entryAt.has(path) && entryAt.get(path).inGraph);
+
+  /** 振る舞いの画面の節の並び。解説の `impact` を、変わったこと → 状況の表 → 増えた状況 → 変わらないこと の節にする。 */
+  const ImpactTopics = (() => {
+    // 骨組みの道筋と、その先の値の種類。`build-pr-explain.py` の Shapes の Impact から導いたものと同じ並びで、
+    // `pr-explain-core-cases.sh` が突き合わせる。文の値は見ない(描くときに文字として入れるだけなので)。
+    const SkeletonKinds = Object.freeze({
+      record: isRecord,
+      records: isListOfRecords,
+      ids: (value) => Array.isArray(value) && value.every((item) => typeof item === "string"),
+      id: (value) => typeof value === "string",
+    });
+    const SkeletonRoutes = Object.freeze([
+      ["impact", "record"],
+      ["impact.changed", "record"],
+      ["impact.changed.before", "records"],
+      ["impact.changed.before[].message", "id"],
+      ["impact.changed.after", "records"],
+      ["impact.changed.after[].message", "id"],
+      ["impact.tables", "records"],
+      ["impact.tables[].rowHeads", "records"],
+      ["impact.tables[].rowHeads[].id", "id"],
+      ["impact.tables[].columnHeads", "records"],
+      ["impact.tables[].columnHeads[].id", "id"],
+      ["impact.tables[].outcomes", "records"],
+      ["impact.tables[].outcomes[].rowHead", "id"],
+      ["impact.tables[].outcomes[].columnHead", "id"],
+      ["impact.tables[].outcomes[].tests", "ids"],
+      ["impact.added", "records"],
+      ["impact.added[].before", "records"],
+      ["impact.added[].before[].message", "id"],
+      ["impact.added[].after", "records"],
+      ["impact.added[].after[].message", "id"],
+      ["impact.added[].tests", "ids"],
+      ["impact.kept", "records"],
+      ["impact.kept[].tests", "ids"],
+    ]);
+    const Labels = Object.freeze({ changed: "変わったこと", kept: "変わらないこと" });
+
+    /** 道筋の先の値を集める。途中が欠けていれば集めない(欠けは検査の管轄)。`[]` で終わる段は配列の各要素へ進む。 */
+    const valuesAt = (value, steps) => {
+      if (steps.length === 0) return [value];
+      const [step, ...rest] = steps;
+      const key = step.replace(/\[\]$/, "");
+      if (!isRecord(value) || value[key] === undefined) return [];
+      const inner = value[key];
+      if (!step.endsWith("[]")) return valuesAt(inner, rest);
+      return Array.isArray(inner) ? inner.flatMap((item) => valuesAt(item, rest)) : [];
+    };
+    const depthOf = ([route]) => route.split(".").length;
+
+    const listOf = (value) => (Array.isArray(value) ? value : []);
+    const optionalText = (value) => (typeof value === "string" ? value : null);
+    const linesOf = (lines) => listOf(lines).map((line) => ({ text: line.text, message: optionalText(line.message) }));
+
+    /**
+     * 解説のテストの id を、テスト画面と同じテスト(状態つき)にする。解説のテストに無い id は外す。
+     * @returns `verifying`(確かめているもの)・`missing`(未実装で、まだ無いもの)・`isGuarded`(確かめているものが 1 件以上)
+     */
+    const evidenceOf = (ids, testAt) => {
+      const found = listOf(ids).filter((id) => testAt.has(id)).map((id) => testAt.get(id));
+      const verifying = found.filter(isVerifying);
+      return { verifying, missing: found.filter((test) => test.status === "todo"), isGuarded: verifying.length > 0 };
+    };
+
+    /** 前後の行が指すやりとりを、書いた順に重複なく。解説に無い id は外し、両端が図の箱かを添える。 */
+    const mechanismsOf = (lines, { messages, entryAt }) => {
+      const ids = [...new Set(lines.map((line) => line.message).filter((id) => id !== null && messages.has(id)))];
+      return ids.map((id) => ({ message: messages.get(id), isDrawn: isDrawnMessage(messages.get(id), entryAt) }));
+    };
+
+    /** 見出しの id が重複していれば先のものだけを残す。 */
+    const firstById = (heads) => heads.filter((head, index) => heads.findIndex((other) => other.id === head.id) === index);
+
+    /** マスの状況の文。行の注があれば添える。 */
+    const situationOf = (row, column) => (typeof row.note === "string" ? `${row.label} · ${column.label}(${row.note})` : `${row.label} · ${column.label}`);
+
+    /** 表のマス。同じ組み合わせを 2 回書いていれば先のもの、書いていなければ null(空き)。 */
+    const cellOf = ({ outcomes, row, column, testAt }) => {
+      const outcome = outcomes.find((candidate) => candidate.rowHead === row.id && candidate.columnHead === column.id);
+      if (outcome === undefined) return null;
+      return {
+        row: row.id,
+        column: column.id,
+        result: outcome.result,
+        was: optionalText(outcome.was),
+        note: optionalText(outcome.note),
+        isChanged: typeof outcome.was === "string",
+        situation: situationOf(row, column),
+        tests: evidenceOf(outcome.tests, testAt),
+      };
+    };
+
+    const headOf = (head) => ({ id: head.id, label: head.label, note: optionalText(head.note) });
+
+    /** 状況の表を、行の見出し × 列の見出しの順のマスにする。見出しに無い id のマスは並べない。 */
+    const tableTopicOf = (table, index, { testAt }) => {
+      const rowHeads = firstById(listOf(table.rowHeads));
+      const columnHeads = firstById(listOf(table.columnHeads));
+      const outcomes = listOf(table.outcomes);
+      const rows = rowHeads.map((row) => ({ head: headOf(row), cells: columnHeads.map((column) => cellOf({ outcomes, row, column, testAt })) }));
+      const cells = rows.flatMap((row) => row.cells).filter((cell) => cell !== null);
+      return {
+        kind: "table",
+        id: `table-${index}`,
+        label: table.label,
+        gist: optionalText(table.gist),
+        text: optionalText(table.text),
+        columns: columnHeads.map(headOf),
+        rows,
+        changedCount: cells.filter((cell) => cell.isChanged).length,
+      };
+    };
+
+    const addedTopicOf = (added, index, context) => {
+      const before = linesOf(added.before);
+      const after = linesOf(added.after);
+      return { kind: "added", id: `added-${index}`, label: added.label, before, after, text: optionalText(added.text), tests: evidenceOf(added.tests, context.testAt), mechanisms: mechanismsOf([...before, ...after], context) };
+    };
+
+    const changedTopicsOf = (changed, context) => {
+      if (!isRecord(changed)) return [];
+      const before = linesOf(changed.before);
+      const after = linesOf(changed.after);
+      return [{ kind: "changed", id: "changed", label: Labels.changed, before, after, text: optionalText(changed.text), mechanisms: mechanismsOf([...before, ...after], context) }];
+    };
+
+    const keptTopicsOf = (kept, { testAt }) => {
+      const lines = listOf(kept).map((line) => ({ text: line.text, tests: evidenceOf(line.tests, testAt) }));
+      return lines.length === 0 ? [] : [{ kind: "kept", id: "kept", label: Labels.kept, lines }];
+    };
+
+    /** 根拠のテストに、その解説のテストの id があるか。 */
+    const cites = (evidence, explainTestId) => [...evidence.verifying, ...evidence.missing].some((test) => test.test.id === explainTestId);
+
+    /** 節の中で、そのテストを根拠に挙げているところ。 */
+    const mentionsIn = (topic, explainTestId) => {
+      const mention = (extra) => ({ topic: topic.id, topicLabel: topic.label, cell: null, situation: null, ...extra });
+      switch (topic.kind) {
+        case "changed":
+          return [];
+        case "table":
+          return topic.rows.flatMap((row) => row.cells).filter((cell) => cell !== null && cites(cell.tests, explainTestId)).map((cell) => mention({ cell: { row: cell.row, column: cell.column }, situation: cell.situation }));
+        case "added":
+          return cites(topic.tests, explainTestId) ? [mention({})] : [];
+        case "kept":
+          return topic.lines.filter((line) => cites(line.tests, explainTestId)).map((line) => mention({ situation: line.text }));
+      }
+    };
+
+    return Object.freeze({
+      SkeletonRoutes,
+      /** 使える解説が無いとき。 */
+      Unexplained: Object.freeze({ kind: "none" }),
+      /**
+       * ページが組み立てに使う `impact` の骨組みを見る。
+       * @returns 型の違う道筋(`impact.tables[].outcomes` の形)。崩れが 2 か所以上なら最も外側のもの。崩れていなければ null
+       */
+      skeletonProblemOf: (explain) => {
+        const broken = SkeletonRoutes.filter(([route, kind]) => valuesAt(explain, route.split(".")).some((value) => !SkeletonKinds[kind](value)));
+        if (broken.length === 0) return null;
+        return broken.reduce((outer, candidate) => (depthOf(candidate) < depthOf(outer) ? candidate : outer))[0];
+      },
+      /**
+       * 解説の `impact` を節の並びにする。節の並びは固定で、書かなかった節は無い(変わらないことが 0 件なら節を作らない)。
+       * @param impact 骨組みの検査を通った解説の `impact`(書いていなければ undefined)
+       * @param tests テスト画面と同じテストの並び(`ExplainedMap` の `tests`)
+       * @param entries 木の項目(やりとりの両端が図の箱かを見る)
+       * @param messages 解説のやりとりを id で引く表
+       * @returns `{kind: "unwritten"}`(`impact` が無い)か `{kind: "written", title, lead, topics}`
+       */
+      create: ({ impact, tests, entries, messages }) => {
+        if (impact === undefined) return { kind: "unwritten" };
+        const testAt = new Map(tests.filter((test) => test.test !== null).map((test) => [test.test.id, test]));
+        const context = { testAt, messages, entryAt: new Map(entries.map((entry) => [entry.path, entry])) };
+        const topics = [
+          ...changedTopicsOf(impact.changed, context),
+          ...listOf(impact.tables).map((table, index) => tableTopicOf(table, index, context)),
+          ...listOf(impact.added).map((added, index) => addedTopicOf(added, index, context)),
+          ...keptTopicsOf(impact.kept, context),
+        ];
+        return { kind: "written", title: impact.title, lead: impact.lead, topics };
+      },
+      /**
+       * そのテストを根拠に挙げている節(表ならマス、変わらないことなら行)を、節の順に引く。
+       * @param explainTestId 解説のテストの id(テスト画面の中の位置ではない)
+       * @returns `{topic, topicLabel, cell, situation}` の並び。`cell` は表のマス(`{row, column}`)で、それ以外は null
+       */
+      mentionsOf: (impactTopics, explainTestId) => (impactTopics.kind === "written" ? impactTopics.topics.flatMap((topic) => mentionsIn(topic, explainTestId)) : []),
+    });
+  })();
+
+  /** 振る舞いの画面の「今の節」。本文のスクロールの位置から、目次と右の欄が指す節を決める。 */
+  const TopicScroll = (() => {
+    const ReadingLine = 140;
+    const EndSlack = 4;
+    return Object.freeze({
+      /**
+       * @param tops 節の上端の、スクロールする領域の上端からの距離(節の順)
+       * @param remaining 下へスクロールできる残りの距離
+       * @returns 今の節の添字。上端が 140px 以内(140 を含む)に入った最後の節で、どれも入っていなければ最初の節。
+       *   残りが 4px 以内なら最後の節(最後の節の上端がそこまで上がらないことがあるため)。節が無ければ null
+       */
+      currentOf: ({ tops, remaining }) => {
+        if (tops.length === 0) return null;
+        if (remaining <= EndSlack) return tops.length - 1;
+        const passed = tops.findLastIndex((top) => top <= ReadingLine);
+        return passed < 0 ? 0 : passed;
+      },
+    });
+  })();
+
   /** 変更の地図(change-map.json)と解説(explain.json)の合流。 */
   const ExplainedMap = (() => {
     const MapVersion = 2;
     const ExplainVersion = 1;
     const ExplainListKeys = ["features", "layerRoles", "concepts", "messages", "flows", "commitStories", "suites", "tests"];

-    const isRecord = (value) => typeof value === "object" && value !== null && !Array.isArray(value);
